mapper.select:
select tc.*, tu.id ownerId, tu.name ownerName, ta.id activityId, ta.name activityName, tdv.id appellationId, tdv.type_value appellationName, tdv2.id needLoanId, tdv2.type_value needLoanName, tdv3.id intentionStateId, tdv3.type_value intentionStateName, tp.id intentionProductId, tp.name intentionProductName, tdv4.id stateId, tdv4.type_value stateName, tdv5.id sourceId, tdv5.type_value sourceName from t_clue tc left join t_user tu on tc.owner_id = tu.id left join t_activity ta on tc.activity_id = ta.id left join t_dic_value tdv on tc.appellation = tdv.id left join t_dic_value tdv2 on tc.need_loan = tdv2.id left join t_dic_value tdv3 on tc.intention_state = tdv3.id left join t_product tp on tc.intention_product = tp.id left join t_dic_value tdv4 on tc.state = tdv4.id left join t_dic_value tdv5 on tc.source = tdv5.id
and tc.full_name like concat('%', #{query.fullName}, '%')
and tc.phone like concat('%', #{query.phone}, '%')
and tc.owner_id = #{query.ownerId}
and tc.activity_id = #{query.activityId}
and tc.appellation = #{query.appellation}
and tc.need_loan = #{query.needLoan}
and tc.intention_state = #{query.intentionState}
and tc.intention_product = #{query.intentionProduct}
and tc.source = #{query.source}
and tc.state = -1
and tc.state = #{query.state}
and tc.state = -1
and COALESCE(tc.state, 0) != -1
order by tc.create_time desc, tc.id desc
